import math
# For ell=t f(t), convolution has I~t"'^2 f(t)''^2. Equation/ell''^2 leaves t''^0 f''^2.
# Test numerical constancy of F for several slowly varying f, including log/loglog factors.
def val(z,kind,n=100000):
    def lf(u):
        if u<=2: return 0.0
        if kind=='"'log': return math.log(u)
        if kind=='sqrtlog': return math.sqrt(math.log(u))
        if kind=='loglog': return math.log(math.log(u))
        if kind=='log_over_loglog': return math.log(u)/math.log(math.log(u))
        return 0.0
    s=0.0
    for i in range(1,n):
        x=i/n
        u=z+math.log2(1-x)
        v=z+math.log2(x)
        s += x*(1-x)*math.exp(lf(u)+lf(v)-2*lf(z))
    return s/n
for kind in ['log','sqrtlog','loglog','log_over_loglog']:
    print(kind, [round(val(z,kind),6) for z in [30,60,90]])
