import numpy as np
from scipy.optimize import minimize_scalar

def c(a,b):
    if abs(a-b)<1e-14: return 1/a
    return (np.log(a)-np.log(b))/(a-b)

def Rperp_u(u,g):
    # s0/s1 = u ; Rperp = (1-g) c(t0,t1)/c(s0,s1), t0/t1=(u+g)/(1-g)
    s0,s1 = u/(1+u), 1/(1+u)
    t0,t1 = s0+g*s1, (1-g)*s1
    return (1-g)*c(t0,t1)/c(s0,s1)

